Add-Type -AssemblyName System.Drawing; $img = [System.Drawing.Image]::FromFile('public\tathastu-logo.png'); $size = [math]::Max($img.Width, $img.Height); $bmp = New-Object System.Drawing.Bitmap $size, $size; $bmp.MakeTransparent(); $g = [System.Drawing.Graphics]::FromImage($bmp); $x = [int](($size - $img.Width) / 2); $y = [int](($size - $img.Height) / 2); $g.DrawImage($img, $x, $y, $img.Width, $img.Height); $bmp.Save('public\favicon.png', [System.Drawing.Imaging.ImageFormat]::Png); $g.Dispose(); $bmp.Dispose(); $img.Dispose();
